    car.h = U.wrapAngle(car.h);
    if (speed < 0.08 && thr < 0.02 && !car.reverse) { car.vx *= 0.8; car.vz *= 0.8; }
    car.x += car.vx * dt;
    car.z += car.vz * dt;

    // --- walls
    const p2 = track.project(car.x, car.z, car.idx, _p2, true);
    const cor = track.corridor(p2.s, p2.d, _cor);
    const t2 = p2.idx, rd2 = p2.road >= 0;   // (on a pit road: its own frame for the walls)
    const w2x = rd2 ? p2.tx : track.tx[t2], w2z = rd2 ? p2.tz : track.tz[t2], n2x = rd2 ? p2.nx : track.nx[t2], n2z = rd2 ? p2.nz : track.nz[t2];
    const c2 = Math.abs(Math.cos(car.h) * w2x + Math.sin(car.h) * w2z);
