        const il = 1 / Math.sqrt(l2), cc = Math.abs((Math.cos(car.h) * ex + Math.sin(car.h) * ez) * il), ss = Math.sqrt(Math.max(0, 1 - cc * cc));
        const hc = Math.min(C.width * 0.5 * cc + C.length * 0.5 * ss, C.length * 0.5);
