    if (finished && b.coolD < 400 && inp.brake > 0.06 && A.toBrk[idx] > 40) inp.brake = 0.06;   // (just past the line: lift and coast)
    if (car.reverse && !inp.reverse) inp.throttle = Math.max(inp.throttle, 0.1);

