      const fk = b.fcK < 1 && ak > 0.03 ? b.fcK + (1 - b.fcK) * Math.min(1, (ak - 0.03) / 0.03) : b.fcK;
      const fr = Math.max(0.06, 1 - lu * lu * fk);
