      car.pitCap = vc < vLim - 0.3 ? ps.pg.cap.kph : 0;   // HUD: the exit-cap sign (e.g. 80) while it holds the car
      ps.v = ps.v < vT ? Math.min(vT, ps.v + PIT_ACC * dt) : Math.max(vT, ps.v - PIT_MAX_DEC * dt);
