    car.rpm = U.expDecay(car.rpm || CFG.car.rpmIdle, Math.max(CFG.car.rpmIdle, CFG.car.rpmMax * kmh / top[g]), 20, dt);
    car.surface = SURF.PIT; car.onKerb = false; car.offTrack = false;
